begin;

select extensions.no_plan();

-- Synthetic-only P6-03 graph. No browser policies exist.
insert into public.organizations (id, legal_name, business_name, slug) values
  ('b8200000-0000-0000-0000-000000000001','P603 Synthetic A Inc.','P603 A','p603-a'),
  ('b8200000-0000-0000-0000-000000000002','P603 Synthetic B Inc.','P603 B','p603-b');
insert into public.branches (id, organization_id, name, slug, code, address_line1, city, province) values
  ('b8300000-0000-0000-0000-000000000001','b8200000-0000-0000-0000-000000000001','P603 A Main','p603-a-main','P603-A','1 Synthetic St','Test City','Test Province'),
  ('b8300000-0000-0000-0000-000000000002','b8200000-0000-0000-0000-000000000002','P603 B Main','p603-b-main','P603-B','2 Synthetic St','Test City','Test Province');
insert into public.providers (id, organization_id, first_name, last_name, provider_type) values
  ('c2100000-0000-0000-0000-000000000001','b8200000-0000-0000-0000-000000000001','Dentist','A','REGULAR'),
  ('c2100000-0000-0000-0000-000000000002','b8200000-0000-0000-0000-000000000002','Dentist','B','REGULAR');

select extensions.columns_are('public','provider_availability_rules',array['id','organization_id','provider_id','branch_id','weekday','starts_at_local','ends_at_local','valid_from','valid_to','active','version','created_at','updated_at'],'provider_availability_rules has only the approved P6-03 fields');
select extensions.ok((select relrowsecurity from pg_class where oid = 'public.provider_availability_rules'::regclass),'provider_availability_rules has RLS enabled');
select extensions.ok(not exists(select 1 from (values(0::oid),((select oid from pg_roles where rolname='anon')),((select oid from pg_roles where rolname='authenticated')),((select oid from pg_roles where rolname='service_role'))) as role(role_oid) cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) as privilege(name) where has_table_privilege(role.role_oid,'public.provider_availability_rules',privilege.name)),'PUBLIC, anon, authenticated, and service_role have no provider_availability_rules privileges');
select extensions.is((select count(*)::integer from pg_policies where schemaname='public' and tablename='provider_availability_rules'),0,'provider_availability_rules is deny-by-default with no browser policies');
select extensions.lives_ok($$insert into public.provider_availability_rules (id,organization_id,provider_id,branch_id,weekday,starts_at_local,ends_at_local,valid_from) values ('c2200000-0000-0000-0000-000000000001','b8200000-0000-0000-0000-000000000001','c2100000-0000-0000-0000-000000000001','b8300000-0000-0000-0000-000000000001',1,time '09:00',time '18:00',date '2026-01-01')$$,'an availability rule accepts a valid weekday interval');
select extensions.throws_ok($$insert into public.provider_availability_rules (organization_id,provider_id,branch_id,weekday,starts_at_local,ends_at_local,valid_from) values ('b8200000-0000-0000-0000-000000000001','c2100000-0000-0000-0000-000000000001','b8300000-0000-0000-0000-000000000002',1,time '09:00',time '18:00',date '2026-01-01')$$,'23503',null,'an availability rule cannot reference a foreign branch through the tenant-safe composite foreign key');
select extensions.throws_ok($$insert into public.provider_availability_rules (organization_id,provider_id,branch_id,weekday,starts_at_local,ends_at_local,valid_from) values ('b8200000-0000-0000-0000-000000000001','c2100000-0000-0000-0000-000000000002','b8300000-0000-0000-0000-000000000001',1,time '09:00',time '18:00',date '2026-01-01')$$,'23503',null,'an availability rule cannot reference a foreign provider through the tenant-safe composite foreign key');
select extensions.throws_ok($$insert into public.provider_availability_rules (organization_id,provider_id,branch_id,weekday,starts_at_local,ends_at_local,valid_from) values ('b8200000-0000-0000-0000-000000000001','c2100000-0000-0000-0000-000000000001','b8300000-0000-0000-0000-000000000001',7,time '09:00',time '18:00',date '2026-01-01')$$,'23514',null,'weekday is bounded to 0..6');
select extensions.throws_ok($$insert into public.provider_availability_rules (organization_id,provider_id,branch_id,weekday,starts_at_local,ends_at_local,valid_from) values ('b8200000-0000-0000-0000-000000000001','c2100000-0000-0000-0000-000000000001','b8300000-0000-0000-0000-000000000001',1,time '18:00',time '09:00',date '2026-01-01')$$,'23514',null,'availability requires starts_at_local before ends_at_local');
select extensions.throws_ok($$insert into public.provider_availability_rules (organization_id,provider_id,branch_id,weekday,starts_at_local,ends_at_local,valid_from,valid_to) values ('b8200000-0000-0000-0000-000000000001','c2100000-0000-0000-0000-000000000001','b8300000-0000-0000-0000-000000000001',1,time '09:00',time '18:00',date '2026-06-01',date '2026-01-01')$$,'23514',null,'availability valid_to cannot precede valid_from');

select extensions.columns_are('public','provider_schedule_exceptions',array['id','organization_id','provider_id','branch_id','exception_type','starts_at','ends_at','reason','created_by','created_at'],'provider_schedule_exceptions has only the approved P6-03 fields');
select extensions.ok((select relrowsecurity from pg_class where oid = 'public.provider_schedule_exceptions'::regclass),'provider_schedule_exceptions has RLS enabled');
select extensions.ok(not exists(select 1 from (values(0::oid),((select oid from pg_roles where rolname='anon')),((select oid from pg_roles where rolname='authenticated')),((select oid from pg_roles where rolname='service_role'))) as role(role_oid) cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) as privilege(name) where has_table_privilege(role.role_oid,'public.provider_schedule_exceptions',privilege.name)),'PUBLIC, anon, authenticated, and service_role have no provider_schedule_exceptions privileges');
select extensions.is((select count(*)::integer from pg_policies where schemaname='public' and tablename='provider_schedule_exceptions'),0,'provider_schedule_exceptions is deny-by-default with no browser policies');
select extensions.lives_ok($$insert into public.provider_schedule_exceptions (organization_id,provider_id,exception_type,starts_at,ends_at,reason) values ('b8200000-0000-0000-0000-000000000001','c2100000-0000-0000-0000-000000000001','LEAVE','2026-03-01 00:00:00+00','2026-03-03 00:00:00+00','leave')$$,'a schedule exception accepts a valid interval and type');
select extensions.lives_ok($$insert into public.provider_schedule_exceptions (organization_id,provider_id,branch_id,exception_type,starts_at,ends_at) values ('b8200000-0000-0000-0000-000000000001','c2100000-0000-0000-0000-000000000001','b8300000-0000-0000-0000-000000000001','UNAVAILABLE','2026-03-04 00:00:00+00','2026-03-04 12:00:00+00')$$,'a branch-scoped exception accepts an organization branch');
select extensions.throws_ok($$insert into public.provider_schedule_exceptions (organization_id,provider_id,branch_id,exception_type,starts_at,ends_at) values ('b8200000-0000-0000-0000-000000000001','c2100000-0000-0000-0000-000000000001','b8300000-0000-0000-0000-000000000002','UNAVAILABLE','2026-03-05 00:00:00+00','2026-03-05 12:00:00+00')$$,'23503',null,'a schedule exception cannot reference a foreign branch');
select extensions.throws_ok($$insert into public.provider_schedule_exceptions (organization_id,provider_id,exception_type,starts_at,ends_at) values ('b8200000-0000-0000-0000-000000000001','c2100000-0000-0000-0000-000000000001','TRIP','2026-03-05 09:00:00+00','2026-03-05 18:00:00+00')$$,'23514',null,'invented exception types are rejected');
select extensions.throws_ok($$insert into public.provider_schedule_exceptions (organization_id,provider_id,exception_type,starts_at,ends_at) values ('b8200000-0000-0000-0000-000000000001','c2100000-0000-0000-0000-000000000001','LEAVE','2026-03-06 12:00:00+00','2026-03-06 08:00:00+00')$$,'23514',null,'schedule exceptions require ends_at after starts_at');

with test_failures as (select finish from extensions.finish() where finish !~ '^1\.\.[0-9]+$')
select case when count(*)=0 then 'P1_TEST_PASS' else string_agg(finish,E'\n') end as p1_test_result from test_failures;

rollback;